/**
 * Standard product returned by every search provider.
 *
 * This is the domain model used throughout the search feature.
 * All providers (Jumia, Konga, Slot, etc.) must map their results
 * into this model.
 */
export interface SearchResult {
  /**
   * Unique identifier generated by the provider.
   */
  id: string;

  /**
   * Product title.
   */
  title: string;

  /**
   * Current selling price.
   */
  price: number;

  /**
   * Product detail page.
   */
  url: string;

  /**
   * Product image.
   */
  image: string;

  /**
   * Provider or store name.
   *
   * Example:
   * "Jumia"
   * "Konga"
   * "Slot"
   */
  store: string;
}
